#ifndef AU8522_INIT_H
#define AU8522_INIT_H
#include <stdint.h>
#include "au8522_regs.h"

enum { AU8522_COMPOSITE_CH1 = 1, AU8522_COMPOSITE_CH2, AU8522_COMPOSITE_CH3, AU8522_COMPOSITE_CH4, AU8522_COMPOSITE_CH4_SIF,
       AU8522_SVIDEO_CH13, AU8522_SVIDEO_CH24 };
enum { AU8522_AUDIO_NONE, AU8522_AUDIO_SIF };

struct Au8522Io {
    virtual ~Au8522Io() {}
    virtual void wr(uint16_t reg, uint8_t value) = 0;
    virtual void msleep(int ms) = 0;
    virtual void err(const char *fmt, ...) = 0;
    bool pal_m = false;
    int vid_input = AU8522_COMPOSITE_CH1, aud_input = AU8522_AUDIO_NONE;
};

static inline void setup_decoder_defaults(Au8522Io &io, bool is_svideo)
{
	int i;
	int filter_coef_type;

	/* Provide reasonable defaults for picture tuning values */
	io.wr(AU8522_TVDEC_SHARPNESSREG009H, 0x07);
	io.wr(AU8522_TVDEC_BRIGHTNESS_REG00AH, 0xed);
	io.wr(AU8522_TVDEC_CONTRAST_REG00BH, 0x79);
	io.wr(AU8522_TVDEC_SATURATION_CB_REG00CH, 0x80);
	io.wr(AU8522_TVDEC_SATURATION_CR_REG00DH, 0x80);
	io.wr(AU8522_TVDEC_HUE_H_REG00EH, 0x00);
	io.wr(AU8522_TVDEC_HUE_L_REG00FH, 0x00);

	/* Other decoder registers */
	io.wr(AU8522_TVDEC_INT_MASK_REG010H, 0x00);

	if (is_svideo)
		io.wr(AU8522_VIDEO_MODE_REG011H, 0x04);
	else
		io.wr(AU8522_VIDEO_MODE_REG011H, 0x00);

	io.wr(AU8522_TVDEC_PGA_REG012H,
			AU8522_TVDEC_PGA_REG012H_CVBS);
	io.wr(AU8522_TVDEC_COMB_MODE_REG015H,
			AU8522_TVDEC_COMB_MODE_REG015H_CVBS);
	io.wr(AU8522_TVDED_DBG_MODE_REG060H,
			AU8522_TVDED_DBG_MODE_REG060H_CVBS);

	if (io.pal_m) {
		io.wr(AU8522_TVDEC_FORMAT_CTRL1_REG061H,
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_FIELD_LEN_525 |
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_LINE_LEN_63_492 |
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_SUBCARRIER_NTSC_AUTO);
		io.wr(AU8522_TVDEC_FORMAT_CTRL2_REG062H,
				AU8522_TVDEC_FORMAT_CTRL2_REG062H_STD_PAL_M);
	} else {
		/* NTSC */
		io.wr(AU8522_TVDEC_FORMAT_CTRL1_REG061H,
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_FIELD_LEN_525 |
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_LINE_LEN_63_492 |
				AU8522_TVDEC_FORMAT_CTRL1_REG061H_SUBCARRIER_NTSC_MN);
		io.wr(AU8522_TVDEC_FORMAT_CTRL2_REG062H,
				AU8522_TVDEC_FORMAT_CTRL2_REG062H_STD_NTSC);
	}
	io.wr(AU8522_TVDEC_VCR_DET_LLIM_REG063H,
			AU8522_TVDEC_VCR_DET_LLIM_REG063H_CVBS);
	io.wr(AU8522_TVDEC_VCR_DET_HLIM_REG064H,
			AU8522_TVDEC_VCR_DET_HLIM_REG064H_CVBS);
	io.wr(AU8522_TVDEC_COMB_VDIF_THR1_REG065H,
			AU8522_TVDEC_COMB_VDIF_THR1_REG065H_CVBS);
	io.wr(AU8522_TVDEC_COMB_VDIF_THR2_REG066H,
			AU8522_TVDEC_COMB_VDIF_THR2_REG066H_CVBS);
	io.wr(AU8522_TVDEC_COMB_VDIF_THR3_REG067H,
			AU8522_TVDEC_COMB_VDIF_THR3_REG067H_CVBS);
	io.wr(AU8522_TVDEC_COMB_NOTCH_THR_REG068H,
			AU8522_TVDEC_COMB_NOTCH_THR_REG068H_CVBS);
	io.wr(AU8522_TVDEC_COMB_HDIF_THR1_REG069H,
			AU8522_TVDEC_COMB_HDIF_THR1_REG069H_CVBS);
	io.wr(AU8522_TVDEC_COMB_HDIF_THR2_REG06AH,
			AU8522_TVDEC_COMB_HDIF_THR2_REG06AH_CVBS);
	io.wr(AU8522_TVDEC_COMB_HDIF_THR3_REG06BH,
			AU8522_TVDEC_COMB_HDIF_THR3_REG06BH_CVBS);
	if (is_svideo) {
		io.wr(AU8522_TVDEC_COMB_DCDIF_THR1_REG06CH,
				AU8522_TVDEC_COMB_DCDIF_THR1_REG06CH_SVIDEO);
		io.wr(AU8522_TVDEC_COMB_DCDIF_THR2_REG06DH,
				AU8522_TVDEC_COMB_DCDIF_THR2_REG06DH_SVIDEO);
	} else {
		io.wr(AU8522_TVDEC_COMB_DCDIF_THR1_REG06CH,
				AU8522_TVDEC_COMB_DCDIF_THR1_REG06CH_CVBS);
		io.wr(AU8522_TVDEC_COMB_DCDIF_THR2_REG06DH,
				AU8522_TVDEC_COMB_DCDIF_THR2_REG06DH_CVBS);
	}
	io.wr(AU8522_TVDEC_COMB_DCDIF_THR3_REG06EH,
			AU8522_TVDEC_COMB_DCDIF_THR3_REG06EH_CVBS);
	io.wr(AU8522_TVDEC_UV_SEP_THR_REG06FH,
			AU8522_TVDEC_UV_SEP_THR_REG06FH_CVBS);
	io.wr(AU8522_TVDEC_COMB_DC_THR1_NTSC_REG070H,
			AU8522_TVDEC_COMB_DC_THR1_NTSC_REG070H_CVBS);
	io.wr(AU8522_REG071H, AU8522_REG071H_CVBS);
	io.wr(AU8522_REG072H, AU8522_REG072H_CVBS);
	io.wr(AU8522_TVDEC_COMB_DC_THR2_NTSC_REG073H,
			AU8522_TVDEC_COMB_DC_THR2_NTSC_REG073H_CVBS);
	io.wr(AU8522_REG074H, AU8522_REG074H_CVBS);
	io.wr(AU8522_REG075H, AU8522_REG075H_CVBS);
	io.wr(AU8522_TVDEC_DCAGC_CTRL_REG077H,
			AU8522_TVDEC_DCAGC_CTRL_REG077H_CVBS);
	io.wr(AU8522_TVDEC_PIC_START_ADJ_REG078H,
			AU8522_TVDEC_PIC_START_ADJ_REG078H_CVBS);
	io.wr(AU8522_TVDEC_AGC_HIGH_LIMIT_REG079H,
			AU8522_TVDEC_AGC_HIGH_LIMIT_REG079H_CVBS);
	io.wr(AU8522_TVDEC_MACROVISION_SYNC_THR_REG07AH,
			AU8522_TVDEC_MACROVISION_SYNC_THR_REG07AH_CVBS);
	io.wr(AU8522_TVDEC_INTRP_CTRL_REG07BH,
			AU8522_TVDEC_INTRP_CTRL_REG07BH_CVBS);
	io.wr(AU8522_TVDEC_AGC_LOW_LIMIT_REG0E4H,
			AU8522_TVDEC_AGC_LOW_LIMIT_REG0E4H_CVBS);
	io.wr(AU8522_TOREGAAGC_REG0E5H,
			AU8522_TOREGAAGC_REG0E5H_CVBS);
	io.wr(AU8522_REG016H, AU8522_REG016H_CVBS);

	/*
	 * Despite what the table says, for the HVR-950q we still need
	 * to be in CVBS mode for the S-Video input (reason unknown).
	 */
	/* filter_coef_type = 3; */
	filter_coef_type = 5;

	/* Load the Video Decoder Filter Coefficients */
	for (i = 0; i < NUM_FILTER_COEF; i++) {
		io.wr(filter_coef[i].reg_name,
				filter_coef[i].reg_val[filter_coef_type]);
	}

	/* It's not clear what these registers are for, but they are always
	   set to the same value regardless of what mode we're in */
	io.wr(AU8522_REG42EH, 0x87);
	io.wr(AU8522_REG42FH, 0xa2);
	io.wr(AU8522_REG430H, 0xbf);
	io.wr(AU8522_REG431H, 0xcb);
	io.wr(AU8522_REG432H, 0xa1);
	io.wr(AU8522_REG433H, 0x41);
	io.wr(AU8522_REG434H, 0x88);
	io.wr(AU8522_REG435H, 0xc2);
	io.wr(AU8522_REG436H, 0x3c);
}

static inline void au8522_setup_cvbs_mode(Au8522Io &io, uint8_t input_mode)
{
	/* here we're going to try the pre-programmed route */
	io.wr(AU8522_MODULE_CLOCK_CONTROL_REG0A3H,
			AU8522_MODULE_CLOCK_CONTROL_REG0A3H_CVBS);

	/* PGA in automatic mode */
	io.wr(AU8522_PGA_CONTROL_REG082H, 0x00);

	/* Enable clamping control */
	io.wr(AU8522_CLAMPING_CONTROL_REG083H, 0x00);

	io.wr(AU8522_INPUT_CONTROL_REG081H, input_mode);

	setup_decoder_defaults(io, false);

	io.wr(AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H,
			AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H_CVBS);
}

static inline void au8522_setup_cvbs_tuner_mode(Au8522Io &io,
					 uint8_t input_mode)
{
	/* here we're going to try the pre-programmed route */
	io.wr(AU8522_MODULE_CLOCK_CONTROL_REG0A3H,
			AU8522_MODULE_CLOCK_CONTROL_REG0A3H_CVBS);

	/* It's not clear why we have to have the PGA in automatic mode while
	   enabling clamp control, but it's what Windows does */
	io.wr(AU8522_PGA_CONTROL_REG082H, 0x00);

	/* Enable clamping control */
	io.wr(AU8522_CLAMPING_CONTROL_REG083H, 0x0e);

	/* Disable automatic PGA (since the CVBS is coming from the tuner) */
	io.wr(AU8522_PGA_CONTROL_REG082H, 0x10);

	/* Set input mode to CVBS on channel 4 with SIF audio input enabled */
	io.wr(AU8522_INPUT_CONTROL_REG081H, input_mode);

	setup_decoder_defaults(io, false);

	io.wr(AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H,
			AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H_CVBS);
}

static inline void au8522_setup_svideo_mode(Au8522Io &io,
				     uint8_t input_mode)
{
	io.wr(AU8522_MODULE_CLOCK_CONTROL_REG0A3H,
			AU8522_MODULE_CLOCK_CONTROL_REG0A3H_SVIDEO);

	/* Set input to Y on Channe1, C on Channel 3 */
	io.wr(AU8522_INPUT_CONTROL_REG081H, input_mode);

	/* PGA in automatic mode */
	io.wr(AU8522_PGA_CONTROL_REG082H, 0x00);

	/* Enable clamping control */
	io.wr(AU8522_CLAMPING_CONTROL_REG083H, 0x00);

	setup_decoder_defaults(io, true);

	io.wr(AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H,
			AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H_CVBS);
}

static inline void disable_audio_input(Au8522Io &io)
{
	io.wr(AU8522_AUDIO_VOLUME_L_REG0F2H, 0x00);
	io.wr(AU8522_AUDIO_VOLUME_R_REG0F3H, 0x00);
	io.wr(AU8522_AUDIO_VOLUME_REG0F4H, 0x00);

	io.wr(AU8522_SYSTEM_MODULE_CONTROL_1_REG0A5H, 0x04);
	io.wr(AU8522_I2S_CTRL_2_REG112H, 0x02);

	io.wr(AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H,
			AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H_SVIDEO);
}

static inline void set_audio_input(Au8522Io &io)
{
	int aud_input = io.aud_input;
	int i;

	/* Note that this function needs to be used in conjunction with setting
	   the input routing via register 0x81 */

	if (aud_input == AU8522_AUDIO_NONE) {
		disable_audio_input(io);
		return;
	}

	if (aud_input != AU8522_AUDIO_SIF) {
		/* The caller asked for a mode we don't currently support */
		io.err("Unsupported audio mode requested! mode=%d\n",
		       aud_input);
		return;
	}

	/* Load the Audio Decoder Filter Coefficients */
	for (i = 0; i < NUM_LPFILTER_COEF; i++) {
		io.wr(lpfilter_coef[i].reg_name,
				lpfilter_coef[i].reg_val[0]);
	}

	/* Set the volume */
	io.wr(AU8522_AUDIO_VOLUME_L_REG0F2H, 0x7F);
	io.wr(AU8522_AUDIO_VOLUME_R_REG0F3H, 0x7F);
	io.wr(AU8522_AUDIO_VOLUME_REG0F4H, 0xff);

	/* Not sure what this does */
	io.wr(AU8522_REG0F9H, AU8522_REG0F9H_AUDIO);

	/* Setup the audio mode to stereo DBX */
	io.wr(AU8522_AUDIO_MODE_REG0F1H, 0x82);
	io.msleep(70);

	/* Start the audio processing module */
	io.wr(AU8522_SYSTEM_MODULE_CONTROL_0_REG0A4H, 0x9d);

	/* Set the audio frequency to 48 KHz */
	io.wr(AU8522_AUDIOFREQ_REG606H, 0x03);

	/* Set the I2S parameters (WS, LSB, mode, sample rate */
	io.wr(AU8522_I2S_CTRL_2_REG112H, 0xc2);

	/* Enable the I2S output */
	io.wr(AU8522_SYSTEM_MODULE_CONTROL_1_REG0A5H, 0x09);
}

static inline void au8522_video_set(Au8522Io &io)
{
	uint8_t input_mode;

	io.wr(0xa4, 1 << 5);

	switch (io.vid_input) {
	case AU8522_COMPOSITE_CH1:
		input_mode = AU8522_INPUT_CONTROL_REG081H_CVBS_CH1;
		au8522_setup_cvbs_mode(io, input_mode);
		break;
	case AU8522_COMPOSITE_CH2:
		input_mode = AU8522_INPUT_CONTROL_REG081H_CVBS_CH2;
		au8522_setup_cvbs_mode(io, input_mode);
		break;
	case AU8522_COMPOSITE_CH3:
		input_mode = AU8522_INPUT_CONTROL_REG081H_CVBS_CH3;
		au8522_setup_cvbs_mode(io, input_mode);
		break;
	case AU8522_COMPOSITE_CH4:
		input_mode = AU8522_INPUT_CONTROL_REG081H_CVBS_CH4;
		au8522_setup_cvbs_mode(io, input_mode);
		break;
	case AU8522_SVIDEO_CH13:
		input_mode = AU8522_INPUT_CONTROL_REG081H_SVIDEO_CH13;
		au8522_setup_svideo_mode(io, input_mode);
		break;
	case AU8522_SVIDEO_CH24:
		input_mode = AU8522_INPUT_CONTROL_REG081H_SVIDEO_CH24;
		au8522_setup_svideo_mode(io, input_mode);
		break;
	default:
	case AU8522_COMPOSITE_CH4_SIF:
		input_mode = AU8522_INPUT_CONTROL_REG081H_CVBS_CH4_SIF;
		au8522_setup_cvbs_tuner_mode(io, input_mode);
		break;
	}
}

#endif
